// Model a 4GB-aligned cage. Offsets are the low 32 bits; base is the high part.
const FOUR_GB = 2 ** 32;
const base = 5 * FOUR_GB;            // some 4GB-aligned cage base

function compress(addr) {
  return addr - base;                // store only the offset within the cage
}
function decompress(offset) {
  return base + offset;              // reconstruct: base + offset
}

// Full addresses that all live inside this cage [base, base + 4GB).
const addrs = [base + 0, base + 16, base + 4096, base + (FOUR_GB - 8)];

let survived = 0;
for (const a of addrs) {
  const off = compress(a);
  if (off >= 0 && off < FOUR_GB && decompress(off) === a) survived++;
}
console.log('roundtrip ok=' + survived + '/' + addrs.length);

